bankProbes = EhVars(:,contains(EhVars,["L07","L08","L09"]));
interProbes = EhVars(:,contains(EhVars,["L10","L11","L12"]));
depths = ["05","10","15","30"];
BankMeanDepth = strcat("LMBankMean",depths);
BankStdevDepth = strcat("LMBankStdev",depths);
InterMeanDepth = strcat("LMInterMean",depths);
InterStdevDepth = strcat("LMInterStdev",depths);
% 
    for i = 1:numel(depths)
        % Calculate means and standard deviations for the cleaned data at
        % each depth and area for bank probes
        LMBankPrbDepth  = lowMarshMinuteTbl_Eh{:, bankProbes(contains(bankProbes, depths(i)))};
        lowMarshMinuteTbl_Eh.(BankMeanDepth(i)) = mean(LMBankPrbDepth, 2, 'omitnan');
        lowMarshMinuteTbl_Eh.(BankStdevDepth(i)) = std(LMBankPrbDepth, 0, 2, 'omitnan');
    end
    for i = 1:numel(depths)
        % Calculate means and standard deviations for the cleaned data at
        % each depth and area for bank probes
        LMInterPrbDepth  = lowMarshMinuteTbl_Eh{:, interProbes(contains(interProbes, depths(i)))};
        lowMarshMinuteTbl_Eh.(InterMeanDepth(i)) = mean(LMInterPrbDepth, 2, 'omitnan');
        lowMarshMinuteTbl_Eh.(InterStdevDepth(i)) = std(LMInterPrbDepth, 0, 2, 'omitnan');
    end


